<script setup>
import {ref,computed} from 'vue';import {RouterLink,useRouter} from 'vue-router'
const open=ref(false),router=useRouter();const links=[['/','首页'],['/chat','AI 对话'],['/essay','作文批改'],['/mistakes','错题本'],['/plan','学习计划'],['/profile','学习档案']]
const username=computed(()=>{try{return JSON.parse(localStorage.getItem('englishmate.user')||'{}').username||'用户'}catch{return'用户'}})
function logout(){localStorage.removeItem('englishmate.token');localStorage.removeItem('englishmate.user');router.push('/login')}
</script>
<template><header class="app-header"><div class="header-inner"><RouterLink class="brand" to="/" @click="open=false"><span class="brand-icon">AI</span><span class="brand-copy"><strong>EnglishMate</strong><small>AI English Assistant</small></span></RouterLink><nav :class="['nav-links',{open}]"><RouterLink v-for="link in links" :key="link[0]" :to="link[0]" active-class="active" @click="open=false">{{link[1]}}</RouterLink></nav><div class="header-right"><span class="user">{{username}}</span><button class="logout" @click="logout">退出</button><button class="menu-btn" aria-label="打开菜单" @click="open=!open"><span></span><span></span></button></div></div></header></template>
<style scoped>.app-header{position:sticky;top:0;z-index:100;height:74px;border-bottom:1px solid rgba(76,86,138,.09);background:rgba(255,255,255,.9);backdrop-filter:blur(22px)}.header-inner{width:min(1240px,calc(100% - 40px));height:100%;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:#252b3d}.brand-icon{width:42px;height:42px;display:grid;place-items:center;border-radius:13px;color:#fff;font-size:13px;font-weight:850;background:linear-gradient(145deg,#665cf5,#4f56e8 58%,#4b9df7)}.brand-copy{display:flex;flex-direction:column}.brand-copy strong{font-size:17px}.brand-copy small{color:#98a2b3;font-size:10px}.nav-links{display:flex;gap:3px}.nav-links a{padding:9px 10px;border-radius:10px;color:#687084;font-size:13px;font-weight:650;text-decoration:none}.nav-links a.active,.nav-links a:hover{color:#4b4bd4;background:#eef0ff}.header-right{display:flex;align-items:center;gap:8px}.user{font-size:12px;color:#70788b}.logout{padding:8px 11px;border:1px solid #e0e3ee;border-radius:10px;background:white;color:#5c6375}.menu-btn{display:none}@media(max-width:900px){.nav-links{position:absolute;left:14px;right:14px;top:66px;padding:10px;display:none;flex-direction:column;background:white;border:1px solid #e5e7ef;border-radius:16px}.nav-links.open{display:flex}.menu-btn{display:block;border:0;background:#f2f4ff;border-radius:10px;padding:10px}.user{display:none}}</style>
